args.script:
const resp = await page.goto('http://localhost:5173/', { waitUntil: 'domcontentloaded' });
await page.waitForTimeout(1000);
const title = await page.title();
const bodyText = await page.locator('body').innerText();
return { status: resp ? resp.status() : null, title, bodySnippet: bodyText.slice(0, 500) };

await page.setViewportSize({ width: 1440, height: 900 });
await page.waitForTimeout(1000);

// Check chessboard elements
const board = page.locator('div[data-boardid], [data-testid="chessboard"], svg, cg-board, .chessboard');
const boardCount = await board.count();

// Let's inspect HTML structure of the board area
const mainHtml = await page.locator('main').innerHTML();
return { boardCount, mainHtmlPreview: mainHtml.slice(0, 1500) };

// Check console logs/errors
const reqs = await page.networkRequests();
// Check what's inside the center column
const centerCol = page.locator('.lg\\:col-span-6, main > div > div').first();
const centerHtml = await page.locator('main').first().innerHTML();

// Let's inspect react-chessboard or chessboard container
const boardArea = page.locator('div:has(> [data-boardid]), div[data-boardid], .chessboard, [style*="aspect-ratio"]');
const boardAreaCount = await boardArea.count();
let boardAreaHtml = '';
if (boardAreaCount > 0) {
  boardAreaHtml = await boardArea.first().innerHTML();
}

return {
  networkCount: reqs.length,
  failedRequests: reqs.filter(r => r.status >= 400 || r.status === 0),
  boardAreaCount,
  boardAreaHtmlSnippet: boardAreaHtml.slice(0, 1000)
};

// Find all divs in main
const centerDiv = page.locator('main .lg\\:col-span-6');
const exists = await centerDiv.count();
let centerHtml = '';
if (exists > 0) {
  centerHtml = await centerDiv.innerHTML();
} else {
  centerHtml = await page.locator('main').innerHTML();
}
return { exists, centerHtml: centerHtml.slice(0, 3000) };

await page.reload({ waitUntil: 'domcontentloaded' });
await page.waitForTimeout(1500);

// Check if any board / squares / pieces are rendered now
const squares = page.locator('[data-square], [data-square-coord], [data-piece]');
const squareCount = await squares.count();

const centerText = await page.locator('main').innerText();
return { squareCount, centerSnippet: centerText.slice(0, 300) };

const reqs = await page.networkRequests();
const viteModules = reqs.map(r => ({ url: r.url, status: r.status, method: r.method }));
return { count: viteModules.length, modules: viteModules.filter(m => m.url.includes('/src/')) };

const tab = await page.context().newPage();
const resp = await tab.goto('http://localhost:5173/src/components/board/ChessboardContainer.tsx');
const content = await tab.locator('body').innerText();
await tab.close();
return { status: resp ? resp.status() : null, length: content.length, snippet: content.slice(0, 2000) };

const tab = await page.context().newPage();
await tab.goto('http://localhost:5173/src/components/board/ChessboardContainer.tsx');
const content = await tab.locator('body').innerText();
await tab.close();

// Look for Chessboard tag and boardWidth in content
const idx = content.indexOf('<Chessboard');
const returnIdx = content.lastIndexOf('return');
return {
  jsxSnippet: content.slice(Math.max(0, idx - 300), Math.min(content.length, idx + 800))
};

const tab = await page.context().newPage();
await tab.goto('http://localhost:5173/src/components/board/ChessboardContainer.tsx');
const content = await tab.locator('body').innerText();
await tab.close();

const matches = [];
let pos = 0;
while ((pos = content.indexOf('Chessboard', pos)) !== -1) {
  matches.push(content.slice(Math.max(0, pos - 100), Math.min(content.length, pos + 250)));
  pos += 10;
  if (matches.length > 5) break;
}

const bwMatches = [];
pos = 0;
while ((pos = content.indexOf('boardWidth', pos)) !== -1) {
  bwMatches.push(content.slice(Math.max(0, pos - 100), Math.min(content.length, pos + 250)));
  pos += 10;
  if (bwMatches.length > 5) break;
}

return { matches, bwMatches };

const tab = await page.context().newPage();
await tab.goto('http://localhost:5173/src/components/board/ChessboardContainer.tsx');
const content = await tab.locator('body').innerText();
await tab.close();

const pos = content.indexOf('lineNumber: 132');
return {
  section: content.slice(Math.max(0, pos - 200), Math.min(content.length, pos + 2500))
};

const tab = await page.context().newPage();
await tab.goto('http://localhost:5173/node_modules/.vite/deps/react-chessboard.js?v=30e3fef2');
const content = await tab.locator('body').innerText();
await tab.close();

// Look for boardWidth or clientWidth in react-chessboard
const bw = content.indexOf('boardWidth');
return {
  length: content.length,
  boardWidthSnippet: content.slice(Math.max(0, bw - 200), Math.min(content.length, bw + 600))
};

const tab = await page.context().newPage();
await tab.goto('http://localhost:5173/node_modules/.vite/deps/react-chessboard.js?v=30e3fef2');
const content = await tab.locator('body').innerText();
await tab.close();

const pos = content.indexOf('function Chessboard(');
return {
  found: pos !== -1,
  snippet: pos !== -1 ? content.slice(pos, pos + 1000) : content.slice(content.lastIndexOf('Chessboard'), content.lastIndexOf('Chessboard') + 1000)
};

const tab = await page.context().newPage();
await tab.goto('http://localhost:5173/node_modules/.vite/deps/react-chessboard.js?v=30e3fef2');
const content = await tab.locator('body').innerText();
await tab.close();

// Find "var Chessboard" or "const Chessboard" or "function " before export
const exportIdx = content.lastIndexOf('export {');
return {
  exportSection: content.slice(Math.max(0, exportIdx - 2000), exportIdx + 100)
};

await page.locator('ref=e3').click();
await page.waitForTimeout(500);

// Check if hint pill or hint banner appears
const bodyText = await page.locator('body').innerText();
const hintPill = page.locator('text=Suggested, text=Hint, [class*="emerald"]');
const hintCount = await hintPill.count();

return { hintCount, textSnippet: bodyText.slice(0, 400) };

await page.waitForTimeout(1500);
const hintPill = page.locator('text=Suggested, text=Hint, [class*="emerald"], text=Play Best Move');
const count = await hintPill.count();
const mainText = await page.locator('main').innerText();
return { count, textSnippet: mainText.slice(0, 500) };
